    private static Path root()throws Exception{
        Path game=FabricLoader.getInstance().getGameDir().toRealPath(),development=game.getParent().getParent(),base=development.resolve("build").toRealPath();
        if(!development.getFileName().toString().matches("p3-selection-development-[a-f0-9]{32}")||!game.equals(development.resolve("mod/run").toRealPath()))throw new IllegalStateException("Not an independent development game");
        var copy=read(development.resolve("development-workspace.json"));if(!copy.get("developmentOnly").getAsBoolean()||!copy.get("result").getAsString().equals("passed"))throw new IllegalStateException("Missing source-copy receipt");
        Path result=Path.of(System.getProperty("voxelstudio.patchTransactionTestRoot")).toRealPath();if(!result.getParent().equals(base)||!result.getFileName().toString().matches("patch-transaction-game-[a-f0-9]{32}"))throw new IllegalStateException("Unsafe test output");
        var auth=read(result.resolve("authorization.json"));if(!auth.get("newWorldOnly").getAsBoolean()||!auth.get("visibleWindowAuthorized").getAsBoolean()||auth.get("modelCalls").getAsInt()!=0||!auth.get("explicitUiFixtureWrites").getAsBoolean()||auth.get("delayedSendFixture").getAsBoolean()!=delayedSendEnabled())throw new IllegalStateException("Invalid bounded fixture authorization");
        worldName=auth.get("worldName").getAsString();if(!worldName.matches("patch-transaction-fixture-[a-f0-9]{32}"))throw new IllegalStateException("Unsafe test world");return result;
    }
    static BridgeClient bridge()throws Exception{var r=root();var marker=read(r.resolve("offline-context-provider.json"));var connection=read(r.resolve("data/connection.json"));if(!marker.get("allProvidersReplaced").getAsBoolean()||marker.get("modelCallsAllowed").getAsInt()!=0||marker.get("pid").getAsLong()!=connection.get("pid").getAsLong())throw new IllegalStateException("Offline Bridge not bound");return new BridgeClient(r);}
    private static JsonObject read(Path file)throws Exception{return JsonParser.parseString(Files.readString(file)).getAsJsonObject();}
    private static SelectionRegion region(int x,int y,int z,int xx,int yy,int zz){return new SelectionRegion(new SelectionRegion.Point(x,y,z),new SelectionRegion.Point(xx,yy,zz));}
