        if(c.player==null||c.getServer()==null)return;Path actual=c.getServer().getSavePath(WorldSavePath.ROOT).toRealPath(),allowed=FabricLoader.getInstance().getGameDir().resolve("saves").resolve(worldName).toRealPath();if(!actual.equals(allowed))throw new IllegalStateException("Entered a non-fixture save");var tool=StudioClient.SELECTION;
        if(stage==1){if(ticks<160||!tool.ready())return;if(Boolean.getBoolean("voxelstudio.iristest")){var api=Class.forName("net.irisshaders.iris.api.v0.IrisApi");if(!(boolean)api.getMethod("isShaderPackInUse").invoke(api.getMethod("getInstance").invoke(null)))throw new IllegalStateException("Iris shader not active");}report.addProperty("irisShaderPackActive",Boolean.getBoolean("voxelstudio.iristest"));c.player.getAbilities().flying=true;c.player.sendAbilitiesUpdate();c.player.refreshPositionAndAngles(-20,-38,-24,-35,25);stage=2;}
        if(stage==2){apply=null;undo=null;candidate=null;tool.cancel();tool.mutate(()->{tool.draft.target(SelectionDraft.Target.EDIT,-1);tool.draft.clear();tool.draft.target(SelectionDraft.Target.CONTEXT,-1);tool.draft.region(region(-14,-60,-14,14,-40,14));tool.draft.target(SelectionDraft.Target.EDIT,-1);tool.draft.region(region(-12,-58,-12,12,-42,12));});tool.read();stage=3;return;}
