        if(stage==7){if(ticks<20)return;c.setScreen(new WorldPatchPlacementScreen(new SelectionScreen(new TitleScreen()),candidate));stage=5;return;}
        if(stage==8){pending=true;WorldPatchPlacementService.current(c.getServer(),c.player.getUuid()).whenComplete((value,error)->c.execute(()->{pending=false;if(error!=null){fail(c,error);return;}if(value==null)return;apply=value;((WorldPatchPlacementScreen)c.currentScreen).close();c.setScreen(null);report.addProperty("closedProgressDoesNotCancelApply",true);stage=9;}));return;}
        if(stage==9){var status=apply.status();if(caseIndex==1&&status.confirmed()>0&&status.confirmed()<status.total()&&!report.has("inFlightConflictInjected")){pending=true;var server=c.getServer();var user=c.player.getUuid();server.execute(()->{try{var world=server.getPlayerManager().getPlayer(user).getServerWorld();if(!world.setBlockState(new BlockPos(13,-45,13),Blocks.DIAMOND_BLOCK.getDefaultState(),2))throw new IllegalStateException("Conflict fixture did not change environment");c.execute(()->{pending=false;report.addProperty("inFlightConflictInjected",true);});}catch(Exception e){c.execute(()->fail(c,e));}});return;}if(caseIndex==2&&status.confirmed()>0&&status.confirmed()<status.total()&&!report.has("explicitCancelDispatched")){c.setScreen(new WorldPatchOperationScreen(new SelectionScreen(new TitleScreen())));stage=90;return;}if(!apply.result().isDone())return;var result=apply.result().getNow(null);var expected=caseIndex==0?WorldPatchPlacementService.State.COMPLETED:caseIndex==1?WorldPatchPlacementService.State.CONFLICT:WorldPatchPlacementService.State.CANCELLED;if(result.state()!=expected||result.confirmed()<1||caseIndex==0&&result.confirmed()!=1000||caseIndex!=0&&result.confirmed()>=1000)throw new IllegalStateException("Unexpected native apply outcome: "+result);Files.writeString(output.resolve("case-"+caseIndex+"-apply.json"),new Gson().toJson(result),StandardOpenOption.CREATE_NEW);if(StudioClient.PATCH_PREVIEW.preview()!=null)throw new IllegalStateException("Handoff retained stale preview");observed.close();observed=null;c.setScreen(new WorldPatchOperationScreen(new SelectionScreen(new TitleScreen())));stage=10;return;}
        if(stage==90){if(!active(c,"显式取消当前事务"))return;press(c,"显式取消当前事务");report.addProperty("explicitCancelDispatched",true);c.currentScreen.close();c.setScreen(null);stage=9;return;}
