    private static void openPlacement(MinecraftClient c){c.setScreen(new WorldPatchPlacementScreen(new SelectionScreen(new TitleScreen()),candidate));pending=true;var server=c.getServer();var user=c.player.getUuid();server.execute(()->{try{observed=dev.voxelstudio.WorldChangeTracker.watch(server.getPlayerManager().getPlayer(user).getServerWorld(),capture.selection().context());preparationRevision=observed.revision();c.execute(()->{pending=false;stage=5;});}catch(Exception e){c.execute(()->fail(c,e));}});}
    private static boolean active(MinecraftClient c,String prefix){return c.currentScreen!=null&&c.currentScreen.children().stream().anyMatch(v->v instanceof ClickableWidget w&&w.visible&&w.active&&w.getMessage().getString().startsWith(prefix));}
    private static void press(MinecraftClient c,String prefix){if(c.currentScreen==null)throw new IllegalStateException("Missing UI for "+prefix);var screen=c.currentScreen;var button=screen.children().stream().filter(v->v instanceof ClickableWidget w&&w.visible&&w.active&&w.getMessage().getString().startsWith(prefix)).map(v->(ClickableWidget)v).findFirst().orElseThrow(()->new IllegalStateException("Missing active button "+prefix));double x=button.getX()+button.getWidth()/2.0,y=button.getY()+button.getHeight()/2.0;if(!screen.mouseClicked(x,y,0))throw new IllegalStateException("Button event unhandled");screen.mouseReleased(x,y,0);}
    private static void screenshot(MinecraftClient c,String name)throws Exception{try(var image=net.minecraft.client.util.ScreenshotRecorder.takeScreenshot(c.getFramebuffer())){image.writeTo(output.resolve(name));}}
    private static void fail(MinecraftClient c,Throwable e){try{if(observed!=null)observed.close();var f=new JsonObject();f.addProperty("result","failed");f.addProperty("stage",stage);f.addProperty("case",caseIndex);f.addProperty("error",String.valueOf(e));f.addProperty("worldDurabilityVerified",false);if(output!=null)Files.writeString(output.resolve("failure.json"),f.toString(),StandardOpenOption.CREATE_NEW);}catch(Exception ignored){}stage=99;c.scheduleStop();}
